 // Computed update arguments write back before a later real state decision.
 {MobAiConfiguredFsm owner(1,1);MobRuntime mob;mob.attack_at_moment=true;const auto destination=mob_ai_name_code("Dest");const auto source=mob_ai_name_code("Source");MobAiParameter value(1);value.integer=5;value.variable_id=destination;owner.variables.emplace(source,value);value.integer=0;owner.variables.emplace(destination,value);MobAiSystemCatalog catalog;catalog.emplace(0xaec1b010U,MobAiSystemDefinition{1,{{1,1}}});catalog.emplace(0x36824cb7U,MobAiSystemDefinition{1,{{1,1}}});mob.current_time=100;MobAiMobQueries queries(owner,mob);MobAiQueryArguments dispatcher(queries);MobAiWritingServices services(catalog,dispatcher);
  MobAiToken call;call.type=4;call.function_id=0xaec1b010U;MobAiToken read;read.type=3;std::copy_n("Source",7,read.text.begin());MobAiToken factor;factor.type=2;factor.number_type=1;factor.integer=3;MobAiToken multiply;multiply.type=8;multiply.opcode=11;MobAiToken end;end.type=5;MobAiConfiguredCondition expression;MobAiToken inner=call;inner.function_id=0x36824cb7U;expression.words[1]=7;expression.tokens={call,inner,read,factor,multiply,end,end};auto& state=owner.states[1];state.update_program.enabled=true;state.update_program.count=1;state.update_program.expressions.push_back(expression);read.text.fill(0);std::copy_n("Dest",5,read.text.begin());MobAiToken limit=factor;limit.integer=20;MobAiToken compare;compare.type=9;compare.opcode=0;MobAiConfiguredCondition test;test.words[1]=3;test.tokens={read,limit,compare};state.transitions.push_back({2,1,{test}});owner.states[2].enter=[&](MobRuntime& subject,MobAiConfiguredFsm& live){check(live.current==1&&!subject.attack_at_moment&&live.variables.at(destination).integer==23);subject.target_id=77;};execute_mob_ai_configured(mob,owner,services);evaluate_mob_ai_configured(mob,owner,services);check(owner.current==1&&owner.variables.at(destination).integer==8);owner.variables.at(source).integer=20;execute_mob_ai_configured(mob,owner,services);evaluate_mob_ai_configured(mob,owner,services);check(owner.current==2&&mob.target_id==77);}
